CREATE TABLE roles (key text PRIMARY KEY CHECK (key IN ('administrator','coordinator','resource_manager','field_officer','viewer')));
INSERT INTO roles VALUES ('administrator'),('coordinator'),('resource_manager'),('field_officer'),('viewer');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE CHECK(email=lower(email)), password_hash text NOT NULL, role text NOT NULL REFERENCES roles(key), active boolean NOT NULL DEFAULT true, session_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (sid varchar PRIMARY KEY, sess json NOT NULL, expire timestamp(6) NOT NULL); CREATE INDEX session_expire_idx ON session(expire);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, role text NOT NULL REFERENCES roles(key), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reference_data (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('incident_category','resource_category','team_type')), name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(kind,name));
INSERT INTO reference_data(kind,name) VALUES ('incident_category','Flood'),('incident_category','Fire'),('incident_category','Medical emergency'),('incident_category','Infrastructure'),('incident_category','Other'),('resource_category','Medical supplies'),('resource_category','Rescue equipment'),('resource_category','Vehicles'),('resource_category','Shelter supplies'),('resource_category','Food and water'),('team_type','Medical'),('team_type','Rescue'),('team_type','Logistics'),('team_type','Fire response');
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('INC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), title text NOT NULL, category_id uuid NOT NULL REFERENCES reference_data(id), description text NOT NULL, severity text NOT NULL CHECK(severity IN ('low','medium','high','critical')), priority text NOT NULL CHECK(priority IN ('low','medium','high','critical')), status text NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','active','controlled','resolved','closed')), location text NOT NULL, reporter_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('RES-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), name text NOT NULL, category_id uuid NOT NULL REFERENCES reference_data(id), description text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'stock' CHECK(kind IN ('stock','asset')), total_quantity integer NOT NULL CHECK(total_quantity>=0), allocated_quantity integer NOT NULL DEFAULT 0 CHECK(allocated_quantity>=0 AND allocated_quantity<=total_quantity), available_quantity integer GENERATED ALWAYS AS (total_quantity-allocated_quantity) STORED, status text NOT NULL DEFAULT 'operational' CHECK(status IN ('operational','maintenance','unavailable')), location text NOT NULL, threshold integer NOT NULL DEFAULT 0 CHECK(threshold>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(kind<>'asset' OR total_quantity=1));
CREATE TABLE resource_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('REQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), incident_id uuid NOT NULL REFERENCES incidents(id), resource_id uuid REFERENCES resources(id), category_id uuid REFERENCES reference_data(id), quantity integer NOT NULL CHECK(quantity>0), issued_quantity integer NOT NULL DEFAULT 0 CHECK(issued_quantity>=0 AND issued_quantity<=quantity), priority text NOT NULL CHECK(priority IN ('low','medium','high','critical')), justification text NOT NULL, requester_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','under_review','approved','partially_fulfilled','rejected','cancelled','completed')), reviewer_id uuid REFERENCES users(id), decision_reason text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((resource_id IS NULL)<>(category_id IS NULL)));
CREATE TABLE allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('ALC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), request_id uuid NOT NULL REFERENCES resource_requests(id), resource_id uuid NOT NULL REFERENCES resources(id), quantity integer NOT NULL CHECK(quantity>0), released_quantity integer NOT NULL DEFAULT 0 CHECK(released_quantity>=0 AND released_quantity<=quantity), responsible_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE allocation_releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), allocation_id uuid NOT NULL REFERENCES allocations(id), quantity integer NOT NULL CHECK(quantity>0), reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE response_teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('TEAM-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), name text NOT NULL, type_id uuid NOT NULL REFERENCES reference_data(id), lead_id uuid NOT NULL REFERENCES users(id), contact text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'operational' CHECK(status IN ('operational','unavailable')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE team_members (team_id uuid NOT NULL REFERENCES response_teams(id), user_id uuid NOT NULL REFERENCES users(id), PRIMARY KEY(team_id,user_id));
CREATE TABLE team_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES response_teams(id), incident_id uuid NOT NULL REFERENCES incidents(id), status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','responding','on_scene','completed','cancelled')), assigned_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE UNIQUE INDEX one_active_team_assignment ON team_assignments(team_id) WHERE status NOT IN ('completed','cancelled');
CREATE TABLE history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, previous_status text, next_status text, note text, actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_id uuid NOT NULL REFERENCES resources(id), allocation_id uuid REFERENCES allocations(id), quantity_delta integer NOT NULL, action text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (actor_id uuid NOT NULL REFERENCES users(id), action text NOT NULL, key text NOT NULL, digest text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(actor_id,action,key));
CREATE INDEX incidents_status_date ON incidents(status,created_at DESC); CREATE INDEX requests_status_date ON resource_requests(status,created_at DESC); CREATE INDEX requests_incident ON resource_requests(incident_id); CREATE INDEX requests_resource ON resource_requests(resource_id); CREATE INDEX resources_category ON resources(category_id); CREATE INDEX allocations_request ON allocations(request_id); CREATE INDEX allocations_resource ON allocations(resource_id); CREATE INDEX assignments_incident ON team_assignments(incident_id); CREATE INDEX members_user ON team_members(user_id); CREATE INDEX audit_date ON audit_logs(created_at DESC); CREATE INDEX history_entity ON history(entity_type,entity_id,created_at); CREATE INDEX audit_actor ON audit_logs(actor_id);
